solution.solution.cpp:
#include <cstdint>
#include <cstdio>
#include <map>
#include <string>

using LPARAM = std::int64_t;
struct KeyInfo { int repeat; int scanCode; bool extended; bool altDown; bool wasDown; bool released; };

KeyInfo decodeKey(LPARAM lParam)
{
    const std::uint32_t v{ static_cast<std::uint32_t>(lParam) };
    return { static_cast<int>(v & 0xFFFF), static_cast<int>((v >> 16) & 0xFF), ((v >> 24) & 1) != 0,
             ((v >> 29) & 1) != 0, ((v >> 30) & 1) != 0, ((v >> 31) & 1) != 0 };
}

LPARAM encodeKey(const KeyInfo& k)
{
    std::uint32_t v{ static_cast<std::uint32_t>(k.repeat) & 0xFFFF };
    v |= (static_cast<std::uint32_t>(k.scanCode) & 0xFF) << 16;
    if (k.extended) v |= 1u << 24;
    if (k.altDown) v |= 1u << 29;
    if (k.wasDown) v |= 1u << 30;
    if (k.released) v |= 1u << 31;
    return static_cast<LPARAM>(v);
}

bool isFirstPress(LPARAM lParam)
{
    const KeyInfo k{ decodeKey(lParam) };
    return !k.released && !k.wasDown;
}

std::string keyName(int vk)
{
    if ((vk >= 'A' && vk <= 'Z') || (vk >= '0' && vk <= '9')) return std::string(1, static_cast<char>(vk));
    if (vk >= 0x70 && vk <= 0x87) return "F" + std::to_string(vk - 0x70 + 1);
    static const std::map<int, std::string> names{
        { 0x08, "Backspace" }, { 0x09, "Tab" }, { 0x0D, "Enter" }, { 0x1B, "Esc" }, { 0x20, "Space" },
        { 0x21, "PageUp" }, { 0x22, "PageDown" }, { 0x23, "End" }, { 0x24, "Home" }, { 0x25, "Left" },
        { 0x26, "Up" }, { 0x27, "Right" }, { 0x28, "Down" }, { 0x2D, "Insert" }, { 0x2E, "Delete" } };
    if (auto it{ names.find(vk) }; it != names.end()) return it->second;
    char buffer[8];
    std::snprintf(buffer, sizeof(buffer), "0x%02X", vk & 0xFF);
    return buffer;
}

unitTests:
TEST("a first press of A") { const KeyInfo k = decodeKey(0x001E0001); CHECK_EQ(k.repeat, 1); CHECK_EQ(k.scanCode, 0x1E); CHECK(!k.extended); CHECK(!k.wasDown); CHECK(!k.released); CHECK(isFirstPress(0x001E0001)); }
TEST("repeat and release") {
    CHECK(!isFirstPress(0x401E0001)); CHECK(decodeKey(0x401E0001).wasDown);
    const KeyInfo up = decodeKey(static_cast<LPARAM>(0xC01E0001u)); CHECK(up.released); CHECK(up.wasDown); CHECK(!isFirstPress(static_cast<LPARAM>(0xC01E0001u)));
}
TEST("extended and Alt") { const KeyInfo k = decodeKey(0x214B0001); CHECK(k.extended); CHECK(k.altDown); CHECK_EQ(k.scanCode, 0x4B); }
TEST("round trip") {
    const KeyInfo k{ 3, 0x48, true, false, true, false }; CHECK_EQ(encodeKey(k), LPARAM{ 0x41480003 });
    const KeyInfo back = decodeKey(encodeKey(k)); CHECK_EQ(back.repeat, 3); CHECK(back.extended); CHECK(back.wasDown);
    CHECK_EQ(encodeKey({ 1, 0x1C, false, false, true, true }), LPARAM{ 0xC01C0001 });
}
TEST("names") { CHECK_EQ(keyName('S'), std::string("S")); CHECK_EQ(keyName('7'), std::string("7")); CHECK_EQ(keyName(0x74), std::string("F5")); CHECK_EQ(keyName(0x87), std::string("F24")); CHECK_EQ(keyName(0x2E), std::string("Delete")); CHECK_EQ(keyName(0xBA), std::string("0xBA")); }

